   518          if ((ms->c.li = CAST(struct level_info *, malloc(len))) == NULL)
   519                  goto free;
   520
   521          ms->event_flags = 0;
   522          ms->error = -1;
   523          for (i = 0; i < MAGIC_SETS; i++)
