   273                  if (access(file, W_OK) == 0)
   274                          if (file_printf(ms, "writable, ") == -1)
   275                                  return -1;
   276                  if (access(file, X_OK) == 0)
   277                          if (file_printf(ms, "executable, ") == -1)
   278                                  return -1;
   279          }
